var KNY={
  init:function(){
    var keys=['str','spd','stm','int','wil','sen'];
    keys.forEach(function(k){
      var bar=g('sb-'+k);if(!bar)return;
      for(var i=1;i<=10;i++){
        var seg=document.createElement('div');
        seg.className='seg';
        seg.setAttribute('data-k',k);seg.setAttribute('data-v',i);
        seg.onclick=(function(kk,vv){return function(){KNY.setStat(kk,vv)}})(k,i);
        bar.appendChild(seg);
      }
    });
    KNY.buildSkills();
  },
  tb:function(n){
    for(var i=0;i<5;i++){
      g('p'+i).classList.toggle('vis',i===n);
      g('nt'+i).classList.toggle('on',i===n);
    }
    S.tab=n;
  },
  onFaction:function(){
    var f=g('i-faction').value;S.faction=f;
    var isSla=(f==='Demon Slayer Corps'||f==='Former Slayer');
    var isDem=(f==='Demon');
    // origin sections
    ['fsec_sla','fsec_dem'].forEach(function(id){g(id).classList.remove('vis')});
    if(isSla)g('fsec_sla').classList.add('vis');
    if(isDem)g('fsec_dem').classList.add('vis');
    // power sections
    ['fsec_bth','fsec_bda'].forEach(function(id){g(id).classList.remove('vis')});
    if(isSla)g('fsec_bth').classList.add('vis');
    if(isDem)g('fsec_bda').classList.add('vis');
    // header badge
    var badge=g('kbadge');var strip=g('fstrip');
    badge.className='kh-badge';strip.className='fact-strip';
    if(isSla){badge.textContent='SLAYER · '+f.toUpperCase();badge.classList.add('sla');strip.classList.add('sla');}
    else if(isDem){badge.textContent='DEMON';badge.classList.add('dem');strip.classList.add('dem');}
    else{badge.textContent='FACTION: '+(f||'—')}
    // skill locks
    KNY.updateLocks();
  },
  onBreath:function(){
    var v=g('p-breath').value;
    var lore=g('breath-lore');
    if(BREATH_LORE[v]){lore.textContent=BREATH_LORE[v];lore.classList.add('vis');}
    else lore.classList.remove('vis');
  },
  setStat:function(k,v){
    var cur=S.stats[k];
    S.stats[k]=(cur===v)?0:v;
    var n=S.stats[k];
    g('sv-'+k).textContent=n;
    var segs=g('sb-'+k).querySelectorAll('.seg');
    segs.forEach(function(s,i){s.classList.toggle('on',i<n)});
  },
  buildSkills:function(){
    var list=g('sk-list');list.innerHTML='';
    SKILLS.forEach(function(sk){
      var row=document.createElement('div');
      row.className='sk-row';row.id='skr_'+sk.id;
      row.setAttribute('data-name',sk.name.toLowerCase());
      row.setAttribute('data-tag',sk.tag);
      row.onclick=(function(id){return function(){KNY.toggleSkill(id)}})(sk.id);
      var restHtml=sk.restrict?'<div class="sk-rest">⊘ '+sk.restrict+'</div>':'';
      row.innerHTML='<div class="sk-chk"></div><div class="sk-bd"><div class="sk-nm">'+sk.name+'</div><span class="sk-tag '+sk.tag+'">'+sk.tag.toUpperCase()+'</span>'+restHtml+'<div class="sk-desc">'+sk.desc+'</div></div><div class="sk-lock-ic" style="display:none">🔒</div>';
      list.appendChild(row);
    });
    KNY.updateLocks();
  },
  toggleSkill:function(id){
    var row=g('skr_'+id);if(!row||row.classList.contains('locked'))return;
    var sel=row.classList.toggle('sel');
    var idx=S.skills.indexOf(id);
    if(sel&&idx<0)S.skills.push(id);
    else if(!sel&&idx>=0)S.skills.splice(idx,1);
    g('sk-count').textContent=S.skills.length;
  },
  updateLocks:function(){
    var isSla=(S.faction==='Demon Slayer Corps'||S.faction==='Former Slayer');
    var isDem=(S.faction==='Demon');
    SKILLS.forEach(function(sk){
      var row=g('skr_'+sk.id);if(!row)return;
      var locked=(sk.tag==='sla'&&isDem)||(sk.tag==='dem'&&isSla);
      row.classList.toggle('locked',locked);
      var lockIc=row.querySelector('.sk-lock-ic');
      if(lockIc)lockIc.style.display=locked?'block':'none';
      if(locked&&row.classList.contains('sel')){
        row.classList.remove('sel');
        var idx=S.skills.indexOf(sk.id);
        if(idx>=0)S.skills.splice(idx,1);
      }
    });
    if(g('sk-count'))g('sk-count').textContent=S.skills.length;
  },
  sf:function(f){
    S.filter=f;
    document.querySelectorAll('.sk-f').forEach(function(b){b.classList.toggle('on',b.getAttribute('data-f')===f)});
    KNY.applyFilter();
  },
  onSearch:function(v){S.search=v.toLowerCase();KNY.applyFilter()},
  applyFilter:function(){
    SKILLS.forEach(function(sk){
      var row=g('skr_'+sk.id);if(!row)return;
      var show=true;
      if(S.filter==='uni'&&sk.tag!=='uni')show=false;
      if(S.filter==='sla'&&sk.tag!=='sla')show=false;
      if(S.filter==='dem'&&sk.tag!=='dem')show=false;
      if(S.filter==='sel'&&!row.classList.contains('sel'))show=false;
      if(S.search){
        var hay=sk.name.toLowerCase()+' '+sk.desc.toLowerCase();
        if(hay.indexOf(S.search)<0)show=false;
      }
      row.classList.toggle('hidden',!show);
    });
  },
  gather:function(){
    var skillNames=S.skills.map(function(id){
      var sk=SKILLS.find(function(s){return s.id===id});return sk?sk.name:id;
    });
    return{
      name:g('i-name').value.trim(),
      alias:g('i-alias').value.trim(),
      age:g('i-age').value.trim(),
      gender:g('i-gender').value,
      height:g('i-height').value.trim(),
      faction:g('i-faction').value,
      appearance:g('i-appear').value.trim(),
      region:g('o-region').value.trim(),
      era:g('o-era').value.trim(),
      rank:g('o-rank').value,
      origin_path:g('o-path').value,
      demon_tier:g('o-tier').value,
      demon_time:g('o-demtime').value.trim(),
      demon_origin:g('o-origin').value.trim(),
